NativeSignal sys0_copy_file(VM& vm, Thread& thread) {
    const uint32_t source_address = thread.stack.pop();
    const uint32_t destination_address = thread.stack.pop();
    if (source_address == 0 || destination_address == 0) {
        thread.stack.push(0);
        return NativeSignal::Continue;
    }
    const auto source = resolve_host_path(
        vm, vm.memory().read_cstring(source_address, thread.base));
    const auto destination = resolve_host_path(
        vm, vm.memory().read_cstring(destination_address, thread.base));
    std::error_code error;
    if (path_exists(destination)) {
        auto permissions = host_files::status(destination, error).permissions();
        if (!error) {
            permissions |= std::filesystem::perms::owner_write;
            host_files::permissions(
                destination, permissions,
                std::filesystem::perm_options::replace, error);
        }
    }
    error.clear();
    const bool copied = host_files::copy_file(
        source, destination,
        std::filesystem::copy_options::overwrite_existing, error);
    thread.stack.push(copied && !error ? 1U : 0U);
    return NativeSignal::Continue;
}
